  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Trazodone, a CNS-active antidepressant with a lipophilic heteroaromatic structure, showed an absolute oral bioavailability of 81% in control subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alprazolam, a lipophilic CNS drug containing a chlorophenyl ring, has an absolute oral bioavailability of 80–100% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Clobazam, a lipophilic CNS drug with a chlorophenyl substituent, is rapidly and extensively absorbed with approximately 87% oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Triazolam, a lipophilic CNS drug with chlorophenyl and fused-ring features, has an absolute oral bioavailability of 62–85%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Tolvaptan, a lipophilic drug with a chlorophenyl and amide-containing core, has a mean absolute oral bioavailability of 56% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to high oral bioavailability: CNS-active lipophilic drugs with chlorophenyl/heteroaromatic features show F values well above 20% (44–100%). The query's tricyclic antidepressant structure is consistent with good absorption, and no evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule itself.",
    "The extent of first-pass metabolism for this tricyclic thioether is not directly quantified, though analogous CNS drugs with substantial metabolism still exceed the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

